INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("ミッションねえ……\nちょうどいいや\nどこまで片付けられるか\n賭けをしようじゃないか", 2.1, 3001100, 2, 1, 100, 130011, "ヤマト", "2030/01/01 14:59:59", 0.0, -416.5, 3001, "2024/10/31 12:00:00");
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("他人から言われた任務を\n言われるままにやるなんざ\n性に合わないんだがね……\nま、報酬は貰っとこうか", 5.68, 3001101, 2, 4, 101, 130011, "ヤマト", "2030/01/01 14:59:59", 0.0, -416.5, 3001, "2024/10/31 12:00:00");
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("なんだい？　やれンなら\nとっとと済ませちまいな。\nフブキが早くやることやれ\nってボヤいてたよ。", 0.0, 3001102, 1, 1, 102, 130011, "ヤマト", "2030/01/01 14:59:59", 0.0, -416.5, 3001, "2024/10/31 12:00:00");
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("え～？　ぼくに頼みごと～？\nどうしちゃおっかな～\nちゃんとお願いできたら\n考えてあげよっかな～？", 0.0, 3002100, 1, 1, 100, 130211, "フブキ", "2030/01/01 14:59:59", 0.0, -416.5, 3002, "2024/10/31 12:00:00");
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("ほらほらぁ、これが\n欲しいんでしょ～？\nほんと、しょうがないよね～\nザコおに～いさん♡", 0.0, 3002101, 1, 1, 101, 130211, "フブキ", "2030/01/01 14:59:59", 0.0, -416.5, 3002, "2024/10/31 12:00:00");
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("へえ～、欲しいんだ～？\nぼくのた・い・せ・つ・な・モ・ノ\nあははっ！　なに考えてんの？\nもうへんふしじゃ～んｗ", 8.53, 3002102, 2, 5, 102, 130211, "フブキ", "2030/01/01 14:59:59", 0.0, -416.5, 3002, "2024/10/31 12:00:00");
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("なになに～？　もしかしてまた\nおねだりするつもりなんだ？\nとか言って、ほんとはぼくに\n会いたいだけだったりして～？", 5.67, 3002103, 1, 7, 103, 130211, "フブキ", "2030/01/01 14:59:59", 0.0, -416.5, 3002, "2024/10/31 12:00:00");
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("ザコお兄さんってぇ\n頼み方もワンパなのぉ～？\nもっと必死にならないと\nぼくの心は動かせないよ～？", 0.0, 3002104, 1, 1, 104, 130211, "フブキ", "2030/01/01 14:59:59", 0.0, -416.5, 3002, "2024/10/31 12:00:00");
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("あのさーザコお兄さん、\nな～んか調子乗ってない？\nぼくのこと、なんでもくれる\nチョロいやつとか思ってたりー？", 0.0, 3002300, 3, 3, 300, 130211, "フブキ", "2030/01/01 14:59:59", 0.0, -416.5, 3004, "2024/10/31 12:00:00");
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("ざんね～ん♪\nうざいお兄さんには、もうな～んにもあげませ～ん♡\nほんとなっさけなーい♪\nばいば～い♡", 0.0, 3002400, 7, 7, 301, 130211, "フブキ", "2030/01/01 14:59:59", 0.0, -416.5, 3005, "2024/10/31 12:00:00");
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("きゃはは、ほんと必死～♡\nは～、面白かった。\n笑えたからいいよ～\nそれ、恵んだげる～♪", 4.4, 3003200, 1, 2, 200, 130211, "フブキ", "2030/01/01 14:59:59", 0.0, -416.5, 3003, "2024/10/31 12:00:00");
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("は～、しょうがないな～♡\nザコお兄さんってば\nほんとよわよわで\n情けないよね～ｗ", 0.0, 3003201, 7, 7, 201, 130211, "フブキ", "2030/01/01 14:59:59", 0.0, -416.5, 3003, "2024/10/31 12:00:00");
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("お兄さんってば、ぼくがいないと\nほんとザッコザコだよね～\nもっと感謝しろし～♪", 5.6, 3003202, 2, 1, 202, 130211, "フブキ", "2030/01/01 14:59:59", 0.0, -416.5, 3003, "2024/10/31 12:00:00");
